package com.hsm.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class SessionFilter extends OncePerRequestFilter { public static final String USER="hsm.user"; private static final Logger log=LoggerFactory.getLogger(SessionFilter.class); private final SessionService sessions; public SessionFilter(SessionService s){sessions=s;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String t=r.getHeader("Authorization");if(t!=null&&t.startsWith("Bearer "))try{r.setAttribute(USER,sessions.require(t.substring(7)));}catch(RuntimeException exception){log.debug("Rejected bearer token for {}: {}",r.getRequestURI(),exception.getMessage());} c.doFilter(r,p);} }
